+static bool test_direct_entry_spans() {
+#ifdef __EMSCRIPTEN__
+    using namespace memory_experiment;
+    struct restore {
+        unsigned old_mode=mode,old_unsafe=eka2l1::common::code_tracking::unsafe_code_mode;
+        ~restore(){mode=old_mode;eka2l1::common::code_tracking::unsafe_code_mode=old_unsafe;g_test_mem=nullptr;}
+    } saved;
+    mode=2;eka2l1::common::code_tracking::unsafe_code_mode=3;
+    // An end-exclusive code address of 2^32 must not turn an internal
+    // backedge into an apparent exit and reuse a changing-base proof.
+    {
+        const std::uint32_t words[]={0xe5910000,0xe2811004,0xe5912000,0xe5913004,0xeafffffau};
+        const auto tr=translate_arm_block(reinterpret_cast<const std::uint8_t*>(words),sizeof(words),0xffffffecu,
+            nullptr,nullptr,true,false,true,true,nullptr,true,arm_ir_policy::write_budget_chunks);
+        if(tr.proved_reads || tr.proved_writes)return false;
+    }
+    const std::vector<std::vector<std::uint32_t>> programs={
+        {0xe5910000,0xe5912004}, // two accesses stay below the threshold
+        {0xe5910000,0xe2811004,0xe1a07001,0xe5972000,0xe5973004}, // ADD and MOV
+        {0xe4910004,0xe4912004,0xe4913004}, // post-indexed writeback
+        {0xe5a10004,0xe5a12004,0xe5113004,0xe5914000}, // stores and alias reads
+        {0xe5910000,0xe2817a01,0xe5972000,0xe5973004}, // 4104-byte span
+        {0xe5910000,0xe2411004,0xe5912000,0xe5113004}, // SUB
+        {0x05910000,0x15912004,0xe5913008}, // conditional accesses
+        {0xe5910000,0x12811004,0xe5912000,0xe5913004}, // conditional pointer update
+        {0xe5911000,0xe5910000,0xe5912004}, // pointer chase
+        {0xe5910000,0xe4912004,0xe5913000,0xe2566001,0x1afffffa}, // changing loop base
+        {0xe5910000,0xe5912004,0xe5913008,0xe2566001,0x1afffffa}, // invariant loop base
+        {0xe5910000,0xe5d54000,0xe5912004,0xe5913008}, // possible byte helper
+        {0xe3560000,0x0a000000,0xe5910000,0xe5912004,0xe5913008}, // interior join
+    };
+    const std::vector<wasm_import_func> imports={{"env","tlb_read32",2,true},{"env","tlb_write32",3,false},
+        {"env","tlb_read8",2,true},{"env","tlb_write8",3,false},{"env","tlb_read16",2,true},{"env","tlb_write16",3,false}};
+    unsigned checks=0;
+    for(bool arena:{false,true}) {
+        // A real 64 MiB allocation makes arena-edge and multi-page proofs valid.
+        const unsigned size=arena?direct_begin+direct_size+0x10000:test_mem::SIZE;
+        test_mem actual(size),reference_memory(size);
+        for(unsigned program=0;program<programs.size();++program) {
+            if(arena && program>=7)continue;
+            const auto &code=programs[program];const auto *bytes=reinterpret_cast<const std::uint8_t*>(code.data());
+            for(bool region:{false,true}) {
+                auto compile=[&](arm_ir_policy policy){return translate_arm_block(bytes,code.size()*4,0x1000,
+                    nullptr,nullptr,true,false,true,region,nullptr,true,policy);};
+                const auto tr=compile(arm_ir_policy::write_budget_chunks);
+                const bool selected=(program>0 && program<7) || (region && program>=10);
+                if(bool(tr.proved_reads+tr.proved_writes)!=selected || bool(tr.func.outlined_callee)!=selected) {
+                    printf("FAIL direct span selection program=%u region=%u reads=%u writes=%u\n",program,region,tr.proved_reads,tr.proved_writes);return false;
+                }
+                const auto module=build_wasm_module({tr.func},imports);
+                const auto original=build_wasm_module({compile(arm_ir_policy::disabled).func},imports);
+                std::vector<std::uint8_t> guard_module;
+                if(selected) {
+                    auto guarded=tr.func;
+                    guarded.outlined_callee=std::make_shared<wasm_func_def>(*tr.func.outlined_callee);
+                    guarded.outlined_callee->body={op_i32_const,0x7f}; // entry-proof failure returns -1
+                    guarded.outlined_callee->outlined_callee.reset();guarded.outlined_callee->outlined_calls.clear();
+                    guard_module=build_wasm_module({guarded},imports);
+                }
+                std::vector<unsigned> addresses=arena
+                    ?std::vector<unsigned>{direct_begin+0x8001,direct_begin+4095,direct_begin+direct_size-8,direct_begin+direct_size}
+                    :std::vector<unsigned>{0x8000,0x8001,0x8ffc,0x7ffc};
+                if(!arena && selected)addresses.push_back(0xfffffffcu);
+                for(auto address:addresses)for(unsigned budget:{0u,1u,2u,3u,8u})for(unsigned flags:{0u,0x40000000u}) {
+                    if(arena && flags)continue;
+                    // Keep the pointer-chasing fixture's loaded pointer valid;
+                    // raw helper stubs do not model faults on arbitrary data.
+                    if(program==8 && (address&3))continue;
+                    std::fill(actual.data.begin(),actual.data.end(),0);
+                    actual.write_code(0x1000,{bytes,bytes+code.size()*4});
+                    if(!arena)for(unsigned a=0x7000;a<0xc000;a+=4)actual.write32(a,0x9000+(a&255));
+                    else {
+                        for(unsigned a=direct_begin;a<direct_begin+0xb000;a+=4)actual.write32(a,a*37);
+                        for(unsigned a=direct_begin+direct_size-8192;a<size;a+=4)actual.write32(a,a*37);
+                    }
+                    reference_memory.data=actual.data;
+                    r12l1::exclusive_monitor monitor(1);auto reference=make_cpu(reference_memory,monitor);
+                    alignas(8)unsigned state[256]{},control[256]{};
