+                    auto resolve=[&]{std::vector<binding> pages;
+                        for(unsigned a=0x1000;a<0xc000;a+=4096)pages.push_back({a,static_cast<unsigned>(reinterpret_cast<std::uintptr_t>(actual.data.data()+a)),3});
+                        if(arena)for(auto a:{direct_begin,direct_begin+direct_size-4096,direct_begin+direct_size})
+                            pages.push_back({a,static_cast<unsigned>(reinterpret_cast<std::uintptr_t>(actual.data.data()+a)),3});
+                        return pages;};
+                    range direct=arena?range{direct_begin,direct_size,static_cast<unsigned>(reinterpret_cast<std::uintptr_t>(actual.data.data()+direct_begin)),3}:range{};
+                    state[state_offsets::AOT_TLB/4]=mapping.enter(1,1,resolve,direct);
+                    std::memcpy(control,state,sizeof(state));g_test_mem=&actual;
+                    if(address==0xfffffffcu) {
+                        // Check wrapping-address rejection without asking raw
+                        // test helpers to emulate a guest abort.
+                        const auto rejected=js_run_aot_wasm(guard_module.data(),guard_module.size(),reinterpret_cast<std::uint8_t*>(state),sizeof(state));
+                        mapping.leave();g_test_mem=nullptr;
