+                        ++checks;continue;
+                    }
+                    if(!arena && program==4) {
+                        alignas(8)unsigned guard_state[256];std::memcpy(guard_state,state,sizeof(state));
+                        if(js_run_aot_wasm(guard_module.data(),guard_module.size(),reinterpret_cast<std::uint8_t*>(guard_state),sizeof(guard_state))!=-1) {
+                            printf("FAIL multi-page proof accepted a single fallback page\n");return false;
+                        }
+                    }
+                    // Prove the valid arena cases actually take the specialized
+                    // body, rather than merely agreeing through its fallback.
+                    const auto &run_module=selected && arena && address<direct_begin+0xb000?guard_module:module;
+                    const int count=js_run_aot_wasm(run_module.data(),run_module.size(),reinterpret_cast<std::uint8_t*>(state),sizeof(state));
+                    if(count<0 || unsigned(count)>budget)return false;
+                    try { if(count)reference->run(count); }
+                    catch(...) { printf("FAIL direct span interpreter exception arena=%u program=%u region=%u address=%x budget=%u count=%d\n",arena,program,region,address,budget,count);return false; }
+                    for(unsigned r=0;r<16;++r)if(state[r]!=reference->get_reg(r)) {
+                        printf("FAIL direct span oracle arena=%u program=%u region=%u address=%x budget=%u reg=%u actual=%x expected=%x\n",arena,program,region,address,budget,r,state[r],reference->get_reg(r));return false;
+                    }
+                    for(auto f:{std::pair<unsigned,unsigned>{state_offsets::NFLAG,31},{state_offsets::ZFLAG,30},
+                            {state_offsets::CFLAG,29},{state_offsets::VFLAG,28},{state_offsets::TFLAG,5}})
+                        if(state[f.first/4]!=((reference->get_cpsr()>>f.second)&1))return false;
+                    if(actual.data!=reference_memory.data){printf("FAIL direct span oracle memory\n");return false;}
+                    // Replay the original emitter from the same seed. The
+                    // interpreter check above is independent of both emitters.
+                    std::fill(actual.data.begin(),actual.data.end(),0);
+                    actual.write_code(0x1000,{bytes,bytes+code.size()*4});
+                    if(!arena)for(unsigned a=0x7000;a<0xc000;a+=4)actual.write32(a,0x9000+(a&255));
+                    else {
+                        for(unsigned a=direct_begin;a<direct_begin+0xb000;a+=4)actual.write32(a,a*37);
+                        for(unsigned a=direct_begin+direct_size-8192;a<size;a+=4)actual.write32(a,a*37);
+                    }
+                    const int original_count=js_run_aot_wasm(original.data(),original.size(),reinterpret_cast<std::uint8_t*>(control),sizeof(control));
+                    mapping.leave();g_test_mem=nullptr;
+                    if(original_count!=count || actual.data!=reference_memory.data) {
+                        printf("FAIL direct span original progress arena=%u program=%u region=%u address=%x budget=%u count=%d original=%d\n",arena,program,region,address,budget,count,original_count);return false;
+                    }
+                    for(unsigned r=0;r<16;++r)if(state[r]!=control[r])return false;
+                    ++checks;
+                }
+            }
+        }
+    }
+    printf("PASS direct entry spans (%u state, flags, memory, budget and guard-selection cases)\n",checks);
+#endif
+    return true;
+}
